-- Identity and mail (S1). Ids are UUIDv7 generated by the service.

CREATE TABLE users (
  id uuid PRIMARY KEY,
  email text NOT NULL,
  display_name text NOT NULL,
  time_zone text NOT NULL,
  display_translation_id text CHECK (display_translation_id IN ('BSB', 'CSB')),
  created_at timestamptz NOT NULL
);
CREATE UNIQUE INDEX users_email_key ON users (lower(email));

CREATE TABLE login_codes (
  id uuid PRIMARY KEY,
  email text NOT NULL,
  code_hash text NOT NULL,
  request_ip text NOT NULL,
  created_at timestamptz NOT NULL,
  expires_at timestamptz NOT NULL,
  consumed_at timestamptz,
  failed_attempts integer NOT NULL DEFAULT 0 CHECK (failed_attempts BETWEEN 0 AND 5),
  email_job_id uuid
);
CREATE INDEX login_codes_open_email ON login_codes (lower(email)) WHERE consumed_at IS NULL;
CREATE INDEX login_codes_email_created ON login_codes (lower(email), created_at);
CREATE INDEX login_codes_ip_created ON login_codes (request_ip, created_at);

CREATE TABLE auth_sessions (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users (id),
  token_hash text NOT NULL,
  created_at timestamptz NOT NULL,
  last_seen_at timestamptz NOT NULL,
  expires_at timestamptz NOT NULL,
  revoked_at timestamptz
);
CREATE UNIQUE INDEX auth_sessions_token_hash_key ON auth_sessions (token_hash);
CREATE INDEX auth_sessions_user_id ON auth_sessions (user_id);

CREATE TABLE email_jobs (
  id uuid PRIMARY KEY,
  kind text NOT NULL CHECK (kind IN ('login_code', 'reminder')),
  idempotency_key text NOT NULL,
  to_address text NOT NULL,
  subject text NOT NULL,
  text_body text NOT NULL,
  html_body text NOT NULL,
  -- Values substituted into {{name}} placeholders at send time, AES-256-GCM sealed; cleared once the job is terminal.
  sealed_secrets text,
  status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'sending', 'sent', 'failed')),
  attempts integer NOT NULL DEFAULT 0,
  next_attempt_at timestamptz NOT NULL,
  claimed_at timestamptz,
  last_error text,
  created_at timestamptz NOT NULL,
  sent_at timestamptz
);
CREATE UNIQUE INDEX email_jobs_idempotency_key ON email_jobs (idempotency_key);
CREATE INDEX email_jobs_status_next ON email_jobs (status, next_attempt_at);
